schema_ddl:
CREATE DOMAIN codice_stato_spedizione AS TEXT CHECK (VALUE IN ('in_preparazione', 'in_transito', 'consegnata', 'restituita'));

CREATE DOMAIN peso_chilogrammi AS NUMERIC(10,2) CHECK (VALUE > 0);

CREATE DOMAIN cap_postale AS TEXT CHECK (VALUE ~ '^[0-9]{5}$');

CREATE TABLE magazzini (
    id INT PRIMARY KEY,
    nome TEXT NOT NULL UNIQUE,
    citta TEXT NOT NULL,
    cap cap_postale NOT NULL
);

CREATE TABLE spedizioni (
    id INT PRIMARY KEY,
    magazzino_id INT NOT NULL REFERENCES magazzini(id),
    destinatario TEXT NOT NULL,
    indirizzo_destinazione TEXT NOT NULL,
    peso_kg peso_chilogrammi NOT NULL,
    stato codice_stato_spedizione NOT NULL DEFAULT 'in_preparazione',
    data_spedizione DATE NOT NULL,
    data_consegna DATE,
    CHECK (data_consegna IS NULL OR data_consegna >= data_spedizione)
);
